package com.example.dale.utils
import android.Manifest import android.app.NotificationChannel import android.app.NotificationManager import android.app.PendingIntent import android.content.Context import android.content.Intent import android.content.pm.PackageManager import android.os.Build import android.provider.Settings import androidx.core.app.NotificationCompat import androidx.core.content.ContextCompat import com.example.dale.R
object AccessibilityStatusNotifier { private const val CHANNEL_ID = "dale_accessibility_required" private const val NOTIFICATION_ID = 4001
fun sync(context: Context) { val appContext = context.applicationContext val sharedPrefs = SharedPreferencesManager.getInstance(appContext) val shouldShow = sharedPrefs.isSetupCompleted() && sharedPrefs.isProtectionEnabled() && !MonitorStartupHelper.isAccessibilityServiceEnabled(appContext)
if (shouldShow) { show(appContext) } else { cancel(appContext) } }
fun show(context: Context) { val appContext = context.applicationContext if (!canPostNotifications(appContext)) return
createChannel(appContext)
val settingsIntent = Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS).apply { addFlags(Intent.FLAG_ACTIVITY_NEW_TASK) } val pendingIntent = PendingIntent.getActivity( appContext, 0, settingsIntent, PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE )
val notification = NotificationCompat.Builder(appContext, CHANNEL_ID) .setSmallIcon(R.mipmap.ic_launcher_round) .setContentTitle("DALE accessibility is off") .setContentText("Tap to enable accessibility and restore app protection.") .setStyle( NotificationCompat.BigTextStyle() .bigText("DALE cannot protect your apps while accessibility is off. Tap to open settings and enable DALE.") ) .setPriority(NotificationCompat.PRIORITY_HIGH) .setCategory(NotificationCompat.CATEGORY_STATUS) .setOngoing(true) .setAutoCancel(false) .setOnlyAlertOnce(true) .setContentIntent(pendingIntent) .build()
appContext.getSystemService(NotificationManager::class.java) .notify(NOTIFICATION_ID, notification) }
fun cancel(context: Context) { context.applicationContext .getSystemService(NotificationManager::class.java) .cancel(NOTIFICATION_ID) }
private fun createChannel(context: Context) { if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) return
val channel = NotificationChannel( CHANNEL_ID, "DALE accessibility required", NotificationManager.IMPORTANCE_HIGH ).apply { description = "Persistent warning when DALE accessibility is disabled" setShowBadge(true) enableVibration(true) }
context.getSystemService(NotificationManager::class.java) .createNotificationChannel(channel) }
private fun canPostNotifications(context: Context): Boolean { return Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU || ContextCompat.checkSelfPermission( context, Manifest.permission.POST_NOTIFICATIONS ) == PackageManager.PERMISSION_GRANTED } }

package com.example.dale.utils
import android.Manifest import android.app.NotificationChannel import android.app.NotificationManager import android.app.PendingIntent import android.content.Context import android.content.Intent import android.content.pm.PackageManager import android.os.Build import android.provider.Settings import androidx.core.app.NotificationCompat import androidx.core.content.ContextCompat import com.example.dale.R
object AccessibilityStatusNotifier { private const val CHANNEL_ID = "dale_accessibility_required" private const val NOTIFICATION_ID = 4001
fun sync(context: Context) { val appContext = context.applicationContext val sharedPrefs = SharedPreferencesManager.getInstance(appContext) val shouldShow = sharedPrefs.isSetupCompleted() && sharedPrefs.isProtectionEnabled() && !MonitorStartupHelper.isAccessibilityServiceEnabled(appContext)
if (shouldShow) { show(appContext) } else { cancel(appContext) } }
fun show(context: Context) { val appContext = context.applicationContext if (!canPostNotifications(appContext)) return
createChannel(appContext)
val settingsIntent = Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS).apply { addFlags(Intent.FLAG_ACTIVITY_NEW_TASK) } val pendingIntent = PendingIntent.getActivity( appContext, 0, settingsIntent, PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE )
val notification = NotificationCompat.Builder(appContext, CHANNEL_ID) .setSmallIcon(R.mipmap.ic_launcher_monochrome) .setContentTitle("DALE accessibility is off") .setContentText("Tap to enable accessibility and restore app protection.") .setStyle( NotificationCompat.BigTextStyle() .bigText("DALE cannot protect your apps while accessibility is off. Tap to open settings and enable DALE.") ) .setPriority(NotificationCompat.PRIORITY_HIGH) .setCategory(NotificationCompat.CATEGORY_STATUS) .setOngoing(true) .setAutoCancel(false) .setOnlyAlertOnce(true) .setContentIntent(pendingIntent) .build()
appContext.getSystemService(NotificationManager::class.java) .notify(NOTIFICATION_ID, notification) }
fun cancel(context: Context) { context.applicationContext .getSystemService(NotificationManager::class.java) .cancel(NOTIFICATION_ID) }
private fun createChannel(context: Context) { if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) return
val channel = NotificationChannel( CHANNEL_ID, "DALE accessibility required", NotificationManager.IMPORTANCE_HIGH ).apply { description = "Persistent warning when DALE accessibility is disabled" setShowBadge(true) enableVibration(true) }
context.getSystemService(NotificationManager::class.java) .createNotificationChannel(channel) }
private fun canPostNotifications(context: Context): Boolean { return Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU || ContextCompat.checkSelfPermission( context, Manifest.permission.POST_NOTIFICATIONS ) == PackageManager.PERMISSION_GRANTED } }

package com.example.dale.utils

import android.content.Context
import android.os.Bundle
import android.util.Log
import com.google.firebase.analytics.FirebaseAnalytics
import java.io.File
import java.time.Instant
import kotlin.concurrent.thread

/**
 * Comprehensive app activity logging system for DALE
 * Logs all app open/close events with timestamps and detection method used
 */
object AppActivityLogger {
    private const val TAG = "AppActivityLogger"
    private const val SECURITY_LOGS = "activity_log.txt"
    private lateinit var context: Context
    private lateinit var firebaseAnalytics: FirebaseAnalytics
    private var loggingEnabled = true

    fun initialize(application: Context) {
        context = application
        firebaseAnalytics = FirebaseAnalytics.getInstance(application)
    }

    fun setLoggingEnabled(enabled: Boolean) {
        loggingEnabled = enabled
    }

    /**
     * Log an app being opened
     * @param packageName Package of the app
     * @param appName Display name of the app
     * @param groupName Group this app belongs to
     * @param detectionMethod Which detection method triggered this
     */
    fun logAppOpened(
        packageName: String,
        appName: String,
        groupName: String,
        detectionMethod: String
    ) {
        if (!loggingEnabled) return

        val timestamp = Instant.now().toString()
        val message = "[$timestamp] APP_OPENED | Group: $groupName | App: $appName ($packageName) | Method: $detectionMethod"

        thread(name = "LogThread-$packageName", isDaemon = true) {
            try {
                // Log to Firebase
                val bundle = Bundle().apply {
                    putString(FirebaseAnalytics.Param.ITEM_ID, packageName)
                    putString(FirebaseAnalytics.Param.ITEM_NAME, appName)
                    putString("group_name", groupName)
                    putString("detection_method", detectionMethod)
                }
                firebaseAnalytics.logEvent("app_opened", bundle)

                val file = File(context.filesDir, SECURITY_LOGS)
                if (!file.exists()) {
                    file.createNewFile()
                }
                file.appendText(message + "\n")
                Log.d(TAG, message)
                // Also log to AppDetection tag for easy filtering
                Log.d("AppDetection", " APP_OPENED: $appName ($packageName) from group '$groupName' [via $detectionMethod]")
            } catch (e: Exception) {
                Log.e(TAG, "Error logging app opened: $packageName", e)
                Log.e("AppDetection", "❌ ERROR_LOGGING_APP_OPENED: $packageName - ${e.message}")
            }
        }
    }

    /**
     * Log an app being closed
     * @param packageName Package of the app
     * @param appName Display name of the app
     * @param groupName Group this app belongs to
     * @param detectionMethod Which detection method detected this
     */
    fun logAppClosed(
        packageName: String,
        appName: String,
        groupName: String,
        detectionMethod: String
    ) {
        if (!loggingEnabled) return

        val timestamp = Instant.now().toString()
        val message = "[$timestamp] APP_CLOSED | Group: $groupName | App: $appName ($packageName) | Method: $detectionMethod"

        thread(name = "LogThread-$packageName", isDaemon = true) {
            try {
                // Log to Firebase
                val bundle = Bundle().apply {
                    putString(FirebaseAnalytics.Param.ITEM_ID, packageName)
                    putString(FirebaseAnalytics.Param.ITEM_NAME, appName)
                    putString("group_name", groupName)
                    putString("detection_method", detectionMethod)
                }
                firebaseAnalytics.logEvent("app_closed", bundle)

                val file = File(context.filesDir, SECURITY_LOGS)
                if (!file.exists()) {
                    file.createNewFile()
                }
                file.appendText(message + "\n")
                Log.d(TAG, message)
                // Also log to AppDetection tag for easy filtering
                Log.d("AppDetection", " APP_CLOSED: $appName ($packageName) from group '$groupName' [via $detectionMethod]")
            } catch (e: Exception) {
                Log.e(TAG, "Error logging app closed: $packageName", e)
                Log.e("AppDetection", "❌ ERROR_LOGGING_APP_CLOSED: $packageName - ${e.message}")
            }
        }
    }

    /**
     * Log a lock screen event
     */
    fun logLockScreenTriggered(
        packageName: String,
        appName: String,
        groupName: String,
        detectionMethod: String
    ) {
        if (!loggingEnabled) return

        val timestamp = Instant.now().toString()
        val message = "[$timestamp] LOCK_SCREEN_TRIGGERED | Group: $groupName | App: $appName ($packageName) | Method: $detectionMethod"

        thread(name = "LogThread-$packageName", isDaemon = true) {
            try {
                // Log to Firebase
                val bundle = Bundle().apply {
                    putString(FirebaseAnalytics.Param.ITEM_ID, packageName)
                    putString(FirebaseAnalytics.Param.ITEM_NAME, appName)
                    putString("group_name", groupName)
                    putString("detection_method", detectionMethod)
                }
                firebaseAnalytics.logEvent("lock_screen_triggered", bundle)

                val file = File(context.filesDir, SECURITY_LOGS)
                if (!file.exists()) {
                    file.createNewFile()
                }
                file.appendText(message + "\n")
                Log.d(TAG, message)
            } catch (e: Exception) {
                Log.e(TAG, "Error logging lock screen triggered: $packageName", e)
            }
        }
    }

    /**
     * Log PIN entry attempt
     */
    fun logPINAttempt(
        packageName: String,
        appName: String,
        groupName: String,
        success: Boolean
    ) {
        if (!loggingEnabled) return

        val timestamp = Instant.now().toString()
        val status = if (success) "SUCCESS" else "FAILED"
        val message = "[$timestamp] PIN_ATTEMPT | Group: $groupName | App: $appName ($packageName) | Status: $status"

        thread(name = "LogThread-$packageName", isDaemon = true) {
            try {
                // Log to Firebase
                val bundle = Bundle().apply {
                    putString(FirebaseAnalytics.Param.ITEM_ID, packageName)
                    putString(FirebaseAnalytics.Param.ITEM_NAME, appName)
                    putString("group_name", groupName)
                    putBoolean("success", success)
                }
                firebaseAnalytics.logEvent("pin_attempt", bundle)

                val file = File(context.filesDir, SECURITY_LOGS)
                if (!file.exists()) {
                    file.createNewFile()
                }
                file.appendText(message + "\n")
                Log.d(TAG, message)
            } catch (e: Exception) {
                Log.e(TAG, "Error logging PIN attempt: $packageName", e)
            }
        }
    }

    /**
     * Get all activity logs
     */
    fun getActivityLogs(): List<String> {
        return try {
            val file = File(context.filesDir, SECURITY_LOGS)
            if (!file.exists()) {
                emptyList()
            } else {
                file.readLines().reversed()  // Most recent first
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error reading activity logs", e)
            emptyList()
        }
    }

    /**
     * Clear all activity logs
     */
    fun clearActivityLogs() {
        thread(name = "ClearLogsThread", isDaemon = true) {
            try {
                val file = File(context.filesDir, SECURITY_LOGS)
                if (file.exists()) {
                    file.delete()
                    Log.d(TAG, "Cleared activity logs")
                }
            } catch (e: Exception) {
                Log.e(TAG, "Error clearing logs", e)
            }
        }
    }

    /**
     * Get last N logs
     */
    fun getLastLogs(limit: Int = 50): List<String> {
        return getActivityLogs().take(limit)
    }

    /**
     * Export logs to a formatted string
     */
    fun exportLogs(): String {
        return getActivityLogs().joinToString("\n")
    }
}

package com.example.dale.utils

import android.content.Context
import android.os.Bundle
import android.util.Log
import com.google.firebase.analytics.FirebaseAnalytics
import java.io.File
import java.time.Instant
import kotlin.concurrent.thread

/**
 * Comprehensive app activity logging system for DALE
 * Logs all app open/close events with timestamps and detection method used
 */
object AppActivityLogger {
    private const val TAG = "AppActivityLogger"
    private const val SECURITY_LOGS = "activity_log.txt"
    private lateinit var context: Context
    private lateinit var firebaseAnalytics: FirebaseAnalytics
    private var loggingEnabled = true

    private fun hasAnalyticsConsent(): Boolean {
        return context.getSharedPreferences("dale_prefs", Context.MODE_PRIVATE)
            .getBoolean("analytics_enabled", false)
    }

    fun initialize(application: Context) {
        context = application
        firebaseAnalytics = FirebaseAnalytics.getInstance(application)
    }

    fun setLoggingEnabled(enabled: Boolean) {
        loggingEnabled = enabled
    }

    /**
     * Log an app being opened
     * @param packageName Package of the app
     * @param appName Display name of the app
     * @param groupName Group this app belongs to
     * @param detectionMethod Which detection method triggered this
     */
    fun logAppOpened(
        packageName: String,
        appName: String,
        groupName: String,
        detectionMethod: String
    ) {
        if (!loggingEnabled || !hasAnalyticsConsent()) return

        val timestamp = Instant.now().toString()
        val message = "[$timestamp] APP_OPENED | Group: $groupName | App: $appName ($packageName) | Method: $detectionMethod"

        thread(name = "LogThread-$packageName", isDaemon = true) {
            try {
                // Log to Firebase without sensitive app/package names
                val bundle = Bundle().apply {
                    putString("group_name", groupName)
                    putString("detection_method", detectionMethod)
                }
                firebaseAnalytics.logEvent("app_opened", bundle)

                val file = File(context.filesDir, SECURITY_LOGS)
                if (!file.exists()) {
                    file.createNewFile()
                }
                file.appendText(message + "\n")
                Log.d(TAG, message)
                // Also log to AppDetection tag for easy filtering
                Log.d("AppDetection", " APP_OPENED: $appName ($packageName) from group '$groupName' [via $detectionMethod]")
            } catch (e: Exception) {
                Log.e(TAG, "Error logging app opened: $packageName", e)
                Log.e("AppDetection", "❌ ERROR_LOGGING_APP_OPENED: $packageName - ${e.message}")
            }
        }
    }

    /**
     * Log an app being closed
     * @param packageName Package of the app
     * @param appName Display name of the app
     * @param groupName Group this app belongs to
     * @param detectionMethod Which detection method detected this
     */
    fun logAppClosed(
        packageName: String,
        appName: String,
        groupName: String,
        detectionMethod: String
    ) {
        if (!loggingEnabled || !hasAnalyticsConsent()) return

        val timestamp = Instant.now().toString()
        val message = "[$timestamp] APP_CLOSED | Group: $groupName | App: $appName ($packageName) | Method: $detectionMethod"

        thread(name = "LogThread-$packageName", isDaemon = true) {
            try {
                // Log to Firebase without sensitive app/package names
                val bundle = Bundle().apply {
                    putString("group_name", groupName)
                    putString("detection_method", detectionMethod)
                }
                firebaseAnalytics.logEvent("app_closed", bundle)

                val file = File(context.filesDir, SECURITY_LOGS)
                if (!file.exists()) {
                    file.createNewFile()
                }
                file.appendText(message + "\n")
                Log.d(TAG, message)
                // Also log to AppDetection tag for easy filtering
                Log.d("AppDetection", " APP_CLOSED: $appName ($packageName) from group '$groupName' [via $detectionMethod]")
            } catch (e: Exception) {
                Log.e(TAG, "Error logging app closed: $packageName", e)
                Log.e("AppDetection", "❌ ERROR_LOGGING_APP_CLOSED: $packageName - ${e.message}")
            }
        }
    }

    /**
     * Log a lock screen event
     */
    fun logLockScreenTriggered(
        packageName: String,
        appName: String,
        groupName: String,
        detectionMethod: String
    ) {
        if (!loggingEnabled || !hasAnalyticsConsent()) return

        val timestamp = Instant.now().toString()
        val message = "[$timestamp] LOCK_SCREEN_TRIGGERED | Group: $groupName | App: $appName ($packageName) | Method: $detectionMethod"

        thread(name = "LogThread-$packageName", isDaemon = true) {
            try {
                // Log to Firebase without sensitive app/package names
                val bundle = Bundle().apply {
                    putString("group_name", groupName)
                    putString("detection_method", detectionMethod)
                }
                firebaseAnalytics.logEvent("lock_screen_triggered", bundle)

                val file = File(context.filesDir, SECURITY_LOGS)
                if (!file.exists()) {
                    file.createNewFile()
                }
                file.appendText(message + "\n")
                Log.d(TAG, message)
            } catch (e: Exception) {
                Log.e(TAG, "Error logging lock screen triggered: $packageName", e)
            }
        }
    }

    /**
     * Log PIN entry attempt
     */
    fun logPINAttempt(
        packageName: String,
        appName: String,
        groupName: String,
        success: Boolean
    ) {
        if (!loggingEnabled || !hasAnalyticsConsent()) return

        val timestamp = Instant.now().toString()
        val status = if (success) "SUCCESS" else "FAILED"
        val message = "[$timestamp] PIN_ATTEMPT | Group: $groupName | App: $appName ($packageName) | Status: $status"

        thread(name = "LogThread-$packageName", isDaemon = true) {
            try {
                // Log to Firebase without sensitive app/package names
                val bundle = Bundle().apply {
                    putString("group_name", groupName)
                    putBoolean("success", success)
                }
                firebaseAnalytics.logEvent("pin_attempt", bundle)

                val file = File(context.filesDir, SECURITY_LOGS)
                if (!file.exists()) {
                    file.createNewFile()
                }
                file.appendText(message + "\n")
                Log.d(TAG, message)
            } catch (e: Exception) {
                Log.e(TAG, "Error logging PIN attempt: $packageName", e)
            }
        }
    }

    /**
     * Get all activity logs
     */
    fun getActivityLogs(): List<String> {
        return try {
            val file = File(context.filesDir, SECURITY_LOGS)
            if (!file.exists()) {
                emptyList()
            } else {
                file.readLines().reversed()  // Most recent first
            }
        } catch (e: Exception) {
            Log.e(TAG, "Error reading activity logs", e)
            emptyList()
        }
    }

    /**
     * Clear all activity logs
     */
    fun clearActivityLogs() {
        thread(name = "ClearLogsThread", isDaemon = true) {
            try {
                val file = File(context.filesDir, SECURITY_LOGS)
                if (file.exists()) {
                    file.delete()
                    Log.d(TAG, "Cleared activity logs")
                }
            } catch (e: Exception) {
                Log.e(TAG, "Error clearing logs", e)
            }
        }
    }

    /**
     * Get last N logs
     */
    fun getLastLogs(limit: Int = 50): List<String> {
        return getActivityLogs().take(limit)
    }

    /**
     * Export logs to a formatted string
     */
    fun exportLogs(): String {
        return getActivityLogs().joinToString("\n")
    }
}

package com.example.dale.utils

import android.util.Base64
import java.security.MessageDigest
import java.security.SecureRandom
import javax.crypto.SecretKeyFactory
import javax.crypto.spec.PBEKeySpec

object HashUtils {
    fun hashPin(pin: String, saltBase64: String? = null): String {
        val salt = if (saltBase64 != null) {
            Base64.decode(saltBase64, Base64.DEFAULT)
        } else {
            val s = ByteArray(16)
            SecureRandom().nextBytes(s)
            s
        }
        val spec = PBEKeySpec(pin.toCharArray(), salt, 10000, 256)
        val factory = SecretKeyFactory.getInstance("PBKDF2WithHmacSHA256")
        val hash = factory.generateSecret(spec).encoded
        val saltStr = Base64.encodeToString(salt, Base64.NO_WRAP)
        val hashStr = Base64.encodeToString(hash, Base64.NO_WRAP)
        return "$saltStr:$hashStr"
    }

    fun verifyPin(inputPin: String, storedHash: String): Boolean {
        if (!storedHash.contains(":")) {
            // fallback for old un-salted SHA256 if needed
            val hashedInput = MessageDigest.getInstance("SHA-256")
                .digest(inputPin.toByteArray())
                .joinToString("") { "%02x".format(it) }
            return hashedInput == storedHash
        }
        val parts = storedHash.split(":")
        if (parts.size != 2) return false
        val saltBase64 = parts[0]
        val expectedHash = hashPin(inputPin, saltBase64)
        return expectedHash == storedHash
    }
}
